name: Auto-close PRs targeting unready issues
on:
  pull_request:
    types: [opened, edited, synchronize]

jobs:
  check-pr:
    runs-on: ubuntu-latest
    steps:
      - name: Check for unready issues
        id: check
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const pr = context.payload.pull_request;

            // Skip if PR is from a maintainer or bot
            const author = pr.user.login;
            if (author.includes('[bot]') || author === 'mlflow-automation' || author === 'mlflow-bot') {
              console.log('Skipping PR from bot or maintainer');
              return;
            }

            // Parse issue references from PR body
            const body = pr.body || '';
            const issueMatches = body.match(/#(\d+)/g);

            // Skip if multiple issues referenced
            if (!issueMatches || issueMatches.length > 1) {
              console.log('Skipping PR with multiple or no issue references');
              return;
            }

            const issueNumber = parseInt(issueMatches[0].substring(1));

            // Get issue details
            try {
              const issueResponse = await github.rest.issues.get({
                owner,
                repo,
                issue_number: issueNumber
              });

              const issue = issueResponse.data;

              // Skip issues created before 2026-03-10
              const creationDate = new Date(issue.created_at);
              const cutoffDate = new Date('2026-03-10');
              if (creationDate < cutoffDate) {
                console.log(`Skipping issue #${issueNumber} created before policy cutoff`);
                return;
              }

              // Check if issue has ready label
              const hasReadyLabel = issue.labels.some(label => label.name === 'ready');

              if (!hasReadyLabel) {
                // Close the PR with a friendly comment
                await github.rest.issues.createComment({
                  owner,
                  repo,
                  issue_number: pr.number,
                  body: `This PR references issue #${issueNumber}, which hasn't been triaged yet (missing the \`ready\` label). Please ensure the referenced issue is properly labeled before this PR can be considered for merging.\n\nThis PR will be automatically closed to maintain our contribution guidelines. You can reopen it once the issue is ready.`
                });

                await github.rest.pulls.update({
                  owner,
                  repo,
                  pull_number: pr.number,
                  state: 'closed'
                });

                console.log(`Closed PR #${pr.number} referencing unready issue #${issueNumber}`);
              }
            } catch (error) {
              console.log(`Error processing issue #${issueNumber}: ${error.message}`);
            }
